import { FC } from 'react';

interface IndexListItem {
    /** 索引键 */
    anchor: string;
    /** 列表项 */
    items: {
        text: string;
        value?: string | number;
        [key: string]: any;
    }[];
}
interface IndexListProps {
    /** 数据列表 */
    data: IndexListItem[];
    /** 当前索引 */
    current?: string;
    /** 是否吸顶 */
    sticky?: boolean;
    /** 偏移量 */
    stickyOffset?: number;
    /** 索引变化回调 */
    onIndexChange?: (anchor: string) => void;
    /** 点击列表项回调 */
    onItemClick?: (item: any, anchor: string) => void;
    /** 自定义类名 */
    className?: string;
}

declare const IndexList: FC<IndexListProps>;

export { IndexList, IndexList as default };
export type { IndexListItem, IndexListProps };
